/**
 * A Webhook Delivery is one event on its way to a Webhook Endpoint, with every
 * attempt and its immutable receipt. A receipt is evidence of an endpoint
 * response, never of a human reading.
 */
export interface WebhookDelivery {
	/** `orgs/{org}/projects/{project}/envs/{env}/webhook_endpoints/{webhook_endpoint}/webhook_deliveries/{webhook_delivery}`. */
	name?: string
	/** `whd_<cell><ulid>`; never reused. */
	readonly uid?: string
	/** Resource metadata. */
	meta?: common.ResourceMeta
	/** The Event delivered. */
	readonly event?: string
	/** The Subscription that fanned it out. */
	readonly subscription?: string
	/** The delivery state. */
	readonly state?: DeliveryState
	/** Every attempt, oldest first. */
	readonly attempts?: DeliveryAttempt[]
	/** When the next attempt is due. */
	readonly nextAttemptTime?: string
	/** The CloudEvents `type` of the event delivered. */
	readonly eventType?: string
}

/**
 * A Webhook Endpoint is an HTTPS receiver that events of its environment
 * whose type matches `spec.event_types` are delivered to, signed per Standard
 * Webhooks (`webhook-id`, `webhook-timestamp`, `webhook-signature`). Failures
 * retry on the fixed schedule (immediately, 5s, 5m, 30m, 2h, 5h, 10h, 10h);
 * exhausted deliveries dead-letter; an endpoint whose attempts keep failing
 * for five days is disabled.
 */
export interface WebhookEndpoint {
	/** `orgs/{org}/projects/{project}/envs/{env}/webhook_endpoints/{webhook_endpoint}`. */
	name?: string
	/** `whe_<cell><ulid>`; never reused. */
	readonly uid?: string
	/** Resource metadata. */
	meta?: common.ResourceMeta
	/** Desired state. */
	spec?: WebhookEndpointSpec
	/** Observed state. */
	readonly status?: WebhookEndpointStatus
}

/** WebhookEndpointSpec is the caller-writable state of a WebhookEndpoint. */
export interface WebhookEndpointSpec {
	/**
	 * The HTTPS URI deliveries are POSTed to; its host resolves to a public
	 * address.
	 */
	uri?: string
	/** Stop delivering; deliveries queue until enabled. */
	disabled?: boolean
	/** At most this many deliveries in flight; default 10. */
	maxConcurrentDeliveries?: number
	/**
	 * Which event types the endpoint receives: an exact type (`order.paid`), a
	 * prefix ending in `.*` (`order.*`), or `*` for every type; default `["*"]`.
	 */
	eventTypes?: string[]
	/**
	 * At most this many attempts start per second; 0 is no limit. Deliveries
	 * over the limit wait their turn; none is dropped.
	 */
	rateLimitPerSecond?: number
}

/** WebhookEndpointStatus is the observed state of a WebhookEndpoint. */
export interface WebhookEndpointStatus {
	/** The generation this status was computed from. */
	readonly observedGeneration?: string
	/** Ready, Reconciling, Stalled. */
	readonly conditions?: common.Condition[]
	/** Whether Events is delivering. */
	readonly state?: WebhookEndpointState
	/** Why Events disabled the endpoint, when it did. */
	readonly disableReason?: string
	/** The last 2xx answer. */
	readonly lastSuccessTime?: string
	/** Consecutive failed delivery attempts since the last 2xx. */
	readonly consecutiveFailureCount?: number
	/**
	 * The Standard Webhooks signing secret (`whsec_…`). Set only in the answer
	 * of CreateWebhookEndpoint and RotateWebhookEndpointSecret; every other
	 * read leaves it empty, and Events never shows it again.
	 */
	readonly signingSecret?: string
	/**
	 * After a rotation, deliveries carry a second signature with the previous
	 * secret until this time.
	 */
	readonly previousSecretExpireTime?: string
}

/** How one delivery attempt ended. */
export type DeliveryAttemptOutcome = 'delivered' | 'retryable_failure' | 'terminal_failure' | 'ambiguous' | (string & {})

/** The state of one webhook delivery. */
export type DeliveryState = 'pending' | 'delivered' | 'dead_lettered' | 'cancelled' | (string & {})

/** The signature scheme an Inbound Endpoint verifies. */
export type InboundSignatureScheme = 'standard_webhooks' | 'stripe' | 'shopify' | 'github' | (string & {})

/** Whether a Webhook Endpoint receives deliveries. */
export type WebhookEndpointState = 'enabled' | 'disabled' | 'failing_disabled' | (string & {})

