/**
 * EventsService is Sylphx Events: the event bus, queues, outbound and inbound
 * webhooks, and realtime channels. Publish, lease, ack, and delivery run in
 * each cell from that cell's snapshot.
 *
 * Namespace of Sylphx Events on `Sylphx`.
 */
export class EventsApi {
	/** The `topics` collection. */
	readonly topics: TopicsCollection
	/** The `events` collection. */
	readonly events: EventsCollection
	/** The `connectors` collection. */
	readonly connectors: ConnectorsCollection
	/** The `subscriptions` collection. */
	readonly subscriptions: SubscriptionsCollection
	/** The `queues` collection. */
	readonly queues: QueuesCollection
	/** The `webhook_endpoints` collection. */
	readonly webhookEndpoints: WebhookEndpointsCollection
	/** The `webhook_deliveries` collection. */
	readonly webhookDeliveries: WebhookDeliveriesCollection
	/** The `inbound_endpoints` collection. */
	readonly inboundEndpoints: InboundEndpointsCollection
	/** The `realtime_channels` collection. */
	readonly realtimeChannels: RealtimeChannelsCollection
	/** The `realtime_messages` collection. */
	readonly realtimeMessages: RealtimeMessagesCollection
	/** The `realtime_members` collection. */
	readonly realtimeMembers: RealtimeMembersCollection

	constructor(client: runtime.Client) {
		this.topics = new TopicsCollection(client)
		this.events = new EventsCollection(client)
		this.connectors = new ConnectorsCollection(client)
		this.subscriptions = new SubscriptionsCollection(client)
		this.queues = new QueuesCollection(client)
		this.webhookEndpoints = new WebhookEndpointsCollection(client)
		this.webhookDeliveries = new WebhookDeliveriesCollection(client)
		this.inboundEndpoints = new InboundEndpointsCollection(client)
		this.realtimeChannels = new RealtimeChannelsCollection(client)
		this.realtimeMessages = new RealtimeMessagesCollection(client)
		this.realtimeMembers = new RealtimeMembersCollection(client)
	}
}

